const r = await tools.ask_user_question({
  questions: [{
    id: "gate",
    header: "拦截强度",
    question: "插件已装好并生效了（版本 0.1.1）。默认档是 warn：只追问、不硬拦。要不要切成 strict——需求没确认前，我连改文件/跑命令都做不了？",
    options: [
      { label: "切成 strict（推荐，最防跑偏）", description: "你确认四段清单之前，写文件和执行命令会被硬门禁拦住。代价是每个稍微模糊的任务都会多一轮确认。" },
      { label: "保持默认 warn", description: "照样反复追问、照样要你点确认，但只是提醒不硬拦，遇到我自己判断能做的时候会更流畅。" },
      { label: "追问力度也调成 grill（刨根问底）", description: "在 strict 基础上，把 intensity 调到最高档，问得更细更狠（可能要多答一两轮）。" }
    ]
  }]
});
console.log(JSON.stringify(r));
